#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
in highp vec4 in_POSITION0;
out highp vec3 vs_TEXCOORD0;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    vs_TEXCOORD0.xyz = in_POSITION0.xyz;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _WorldSpaceLightPos0;
uniform 	mediump vec4 _SunDiscColor;
uniform 	mediump vec4 _SunHaloColor;
uniform 	mediump vec4 _HorizonLineColor;
uniform 	mediump vec4 _SkyGradientTop;
uniform 	mediump vec4 _SkyGradientBottom;
uniform 	mediump float _SunDiscMultiplier;
uniform 	mediump float _SunDiscExponent;
uniform 	mediump float _SunHaloExponent;
uniform 	mediump float _SunHaloContribution;
uniform 	mediump float _HorizonLineExponent;
uniform 	mediump float _HorizonLineContribution;
uniform 	mediump float _SkyGradientExponent;
in highp  vec3 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
mediump float u_xlat16_0;
vec3 u_xlat1;
vec3 u_xlat2;
vec3 u_xlat3;
vec3 u_xlat4;
vec3 u_xlat6;
float u_xlat16;
void main()
{
    u_xlat16_0 = max(_SkyGradientExponent, 9.99999975e-05);
    u_xlat16_0 = float(1.0) / u_xlat16_0;
    u_xlat1.x = dot(vs_TEXCOORD0.xyz, vs_TEXCOORD0.xyz);
    u_xlat1.x = inversesqrt(u_xlat1.x);
    u_xlat1.xyz = u_xlat1.xxx * vs_TEXCOORD0.xyz;
    u_xlat16 = u_xlat1.y;
    u_xlat16 = clamp(u_xlat16, 0.0, 1.0);
    u_xlat16 = log2(u_xlat16);
    u_xlat16 = u_xlat16_0 * u_xlat16;
    u_xlat16 = exp2(u_xlat16);
    u_xlat2.xyz = _SkyGradientTop.xyz + (-_SkyGradientBottom.xyz);
    u_xlat2.xyz = vec3(u_xlat16) * u_xlat2.xyz + _SkyGradientBottom.xyz;
    u_xlat3.xyz = (-u_xlat2.xyz) + _HorizonLineColor.xyz;
    u_xlat16 = -abs(u_xlat1.y) + 1.0;
    u_xlat16 = log2(u_xlat16);
    u_xlat16 = u_xlat16 * _HorizonLineExponent;
    u_xlat16 = exp2(u_xlat16);
    u_xlat16 = u_xlat16 * _HorizonLineContribution;
    u_xlat2.xyz = vec3(u_xlat16) * u_xlat3.xyz + u_xlat2.xyz;
    u_xlat3.xyz = (-u_xlat2.xyz) + _SunHaloColor.xyz;
    u_xlat16 = dot(_WorldSpaceLightPos0.xyz, _WorldSpaceLightPos0.xyz);
    u_xlat16 = inversesqrt(u_xlat16);
    u_xlat4.xyz = vec3(u_xlat16) * _WorldSpaceLightPos0.xyz;
    u_xlat1.x = dot(u_xlat1.xyz, u_xlat4.xyz);
    u_xlat1.x = clamp(u_xlat1.x, 0.0, 1.0);
    u_xlat1.x = log2(u_xlat1.x);
    u_xlat1.xy = u_xlat1.xx * vec2(_SunHaloExponent, _SunDiscExponent);
    u_xlat1.xy = exp2(u_xlat1.xy);
    u_xlat1.xy = u_xlat1.yx * vec2(_SunDiscMultiplier, _SunHaloContribution);
    u_xlat6.xyz = u_xlat1.yyy * u_xlat3.xyz + u_xlat2.xyz;
    u_xlat1.x = u_xlat1.x;
    u_xlat1.x = clamp(u_xlat1.x, 0.0, 1.0);
    u_xlat2.xyz = (-u_xlat6.xyz) + _SunDiscColor.xyz;
    u_xlat1.xyz = u_xlat1.xxx * u_xlat2.xyz + u_xlat6.xyz;
    SV_Target0.xyz = u_xlat1.xyz;
    SV_Target0.w = 1.0;
    return;
}
